import{_ as l,r as t,o as i,c as u,e as p,a as n,s as e,d as a}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Событие - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Основы использования","slug":"основы-использования","link":"#основы-использования","children":[]},{"level":2,"title":"Подписка на события","slug":"подписка-на-события","link":"#подписка-на-события","children":[{"level":3,"title":"Где регистрировать слушателей","slug":"где-регистрировать-слушателеи","link":"#где-регистрировать-слушателеи","children":[]},{"level":3,"title":"Подписка с приоритетом","slug":"подписка-с-приоритетом","link":"#подписка-с-приоритетом","children":[]},{"level":3,"title":"Остановка событий","slug":"остановка-событии","link":"#остановка-событии","children":[]},{"level":3,"title":"Слушатели с маской","slug":"слушатели-с-маскои","link":"#слушатели-с-маскои","children":[]}]},{"level":2,"title":"Вызов событий","slug":"вызов-событии","link":"#вызов-событии","children":[]},{"level":2,"title":"Передача аргументов по ссылке","slug":"передача-аргументов-по-ссылке","link":"#передача-аргументов-по-ссылке","children":[{"level":3,"title":"Отложенные события","slug":"отложенные-события","link":"#отложенные-события","children":[]}]},{"level":2,"title":"Использование классов в качестве слушателей","slug":"использование-классов-в-качестве-слушателеи","link":"#использование-классов-в-качестве-слушателеи","children":[{"level":3,"title":"Подписка на отдельные методы","slug":"подписка-на-отдельные-методы","link":"#подписка-на-отдельные-методы","children":[]},{"level":3,"title":"Подписка на весь класс","slug":"подписка-на-весь-класс","link":"#подписка-на-весь-класс","children":[]}]},{"level":2,"title":"Трейт Event Emitter","slug":"треит-event-emitter","link":"#треит-event-emitter","children":[]}],"relativePath":"3.x/ru/extend/services/event.md","filePath":"3.x/ru/extend/services/event.md"}'),r={name:"3.x/ru/extend/services/event.md"};function k(d,s,g,v,h,m){const o=t("pre-heading"),c=t("post-heading");return i(),u("div",null,[p(o),s[0]||(s[0]=n("h1",null,"Событие",-1)),p(c),s[1]||(s[1]=e(`<h2 id="основы-использования"><a href="#основы-использования" class="header-anchor">#</a> Основы использования</h2><p>Класс <code>Event</code> предоставляет простую реализацию паттерна «наблюдатель», позволяя вам подписываться и слушать события в вашем приложении. Например, вы можете слушать, когда пользователь входит в систему, и обновлять дату его последнего входа.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">last_login</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DateTime</span><span class="token punctuation">;</span>
    <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Это событие доступно с помощью метода <code>Event::fire</code>, который вызывается как часть логики входа пользователя, тем самым делая логику расширяемой.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,5)),s[2]||(s[2]=n("div",{class:"custom-block tip"},[n("p",null,[a("Полный список всех событий, доступных в самом October CMS, смотрите в "),n("a",{href:"https://octobercms.com/docs/api",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("документации API"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(".")])],-1)),s[3]||(s[3]=e(`<h2 id="подписка-на-события"><a href="#подписка-на-события" class="header-anchor">#</a> Подписка на события</h2><p>Метод <code>Event::listen</code> используется в основном для подписки на события и может быть вызван из любого места в коде вашего приложения. Первый аргумент — имя события.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Второй аргумент может быть замыканием, которое определяет, что должно произойти при вызове события. Замыкание может принимать необязательные аргументы, предоставляемые вызывающим событием.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$arg1</span><span class="token punctuation">,</span> <span class="token variable">$arg2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Do something</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете передать ссылку на любой вызываемый объект или выделенный класс события, и он будет использоваться вместо этого.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;LoginHandler&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Вызываемый метод может выбрать, указать все, некоторые или ни одного аргумента. В любом случае событие не выбросит ошибок, если только не указано слишком много аргументов.</p></div><h3 id="где-регистрировать-слушателеи"><a href="#где-регистрировать-слушателеи" class="header-anchor">#</a> Где регистрировать слушателей</h3><p>Наиболее распространённое место — метод <code>boot</code> <a href="./../extending.html">файла регистрации плагина</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Альтернативно плагины могут предоставить файл с именем <strong>init.php</strong> в директории плагина, который вы можете использовать для размещения логики регистрации событий. Например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Поскольку ни один из этих подходов не является изначально «правильным», выберите подход, который вам удобен, исходя из размера вашего приложения.</p><h3 id="подписка-с-приоритетом"><a href="#подписка-с-приоритетом" class="header-anchor">#</a> Подписка с приоритетом</h3><p>Вы также можете указать приоритет третьим аргументом при подписке на события. Слушатели с более высоким приоритетом будут запущены первыми, а слушатели с одинаковым приоритетом будут запущены в порядке подписки.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Run first</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Run second</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="остановка-событии"><a href="#остановка-событии" class="header-anchor">#</a> Остановка событий</h3><p>Иногда вы можете захотеть остановить распространение события к другим слушателям. Вы можете сделать это, вернув <code>false</code> из вашего слушателя:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Handle the event</span>

    <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="слушатели-с-маскои"><a href="#слушатели-с-маскои" class="header-anchor">#</a> Слушатели с маской</h3><p>При регистрации слушателя события вы можете использовать звёздочки для указания слушателей с маской. Слушатели с маской получают сначала имя вызванного события, а затем параметры, переданные через событие в виде массива.</p><p>Следующий слушатель обрабатывает все события, начинающиеся с <code>foo.</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo.*&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Handle the event...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете использовать метод <code>Event::firing</code> для определения, какое именно событие было вызвано.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo.*&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">firing</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;foo.bar&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="вызов-событии"><a href="#вызов-событии" class="header-anchor">#</a> Вызов событий</h2><p>Вы можете использовать метод <code>Event::fire</code> в любом месте вашего кода, чтобы сделать логику расширяемой. Это означает, что другие разработчики или даже ваш собственный внутренний код могут «подключиться» к этой точке кода и внедрить специфическую логику. Первым аргументом должно быть имя события.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;myevent&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Всегда хорошей практикой является добавление префикса пространства имён вашего плагина к именам событий — это предотвратит конфликты с другими плагинами.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Второй аргумент — массив значений, которые будут переданы в качестве аргументов слушателю, подписанному на событие.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$arg1</span><span class="token punctuation">,</span> <span class="token variable">$arg2</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Третий аргумент указывает, должно ли событие быть останавливающим, то есть должно ли оно остановиться, если возвращено «ненулевое» значение. По умолчанию этот аргумент установлен в false.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если событие является останавливающим, первое возвращённое значение будет захвачено.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Single result, event halted</span>
<span class="token variable">$result</span> <span class="token operator">=</span> <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В противном случае возвращается коллекция всех ответов от всех событий в виде массива.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Multiple results, all events fired</span>
<span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="передача-аргументов-по-ссылке"><a href="#передача-аргументов-по-ссылке" class="header-anchor">#</a> Передача аргументов по ссылке</h2><p>При обработке или фильтрации значения, переданного в событие, вы можете добавить к переменной префикс <code>&amp;</code> для передачи по ссылке. Это позволяет нескольким слушателям манипулировать результатом и передавать его следующему.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При прослушивании события аргумент также должен быть объявлен с символом <code>&amp;</code> в определении замыкания. В примере ниже к переменной <code>$content</code> будет добавлено «AB» к результату.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$content</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;A&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$content</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;B&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="отложенные-события"><a href="#отложенные-события" class="header-anchor">#</a> Отложенные события</h3><p>Вызов событий может быть отложен <a href="./queue.html">совместно с очередями</a>. Используйте метод <code>Event::queue</code> для «постановки в очередь» события для вызова, но не его немедленного вызова.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете использовать метод <code>Event::flush</code> для сброса всех событий в очереди.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">flush</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="использование-классов-в-качестве-слушателеи"><a href="#использование-классов-в-качестве-слушателеи" class="header-anchor">#</a> Использование классов в качестве слушателей</h2><p>В некоторых случаях вы можете захотеть использовать класс для обработки события вместо Closure. Класс-слушатели события будут разрешены из <a href="./application.html">контейнера IoC приложения</a>, предоставляя вам полную мощь внедрения зависимостей для ваших слушателей.</p><h3 id="подписка-на-отдельные-методы"><a href="#подписка-на-отдельные-методы" class="header-anchor">#</a> Подписка на отдельные методы</h3><p>Класс события может быть зарегистрирован методом <code>Event::listen</code> как любой другой, передавая имя класса в виде строки.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token class-name static-context">LoginHandler</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>По умолчанию будет вызван метод <code>handle</code> класса <code>LoginHandler</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">LoginHandler</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">handle</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Если вы не хотите использовать метод <code>handle</code> по умолчанию, вы можете указать имя метода, на который следует подписаться.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token class-name static-context">LoginHandler</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;onLogin&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="подписка-на-весь-класс"><a href="#подписка-на-весь-класс" class="header-anchor">#</a> Подписка на весь класс</h3><p>Подписчики событий — это классы, которые могут подписываться на несколько событий изнутри самого класса. Подписчики должны определить метод <code>subscribe</code>, которому будет передан экземпляр диспетчера событий.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UserEventHandler</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * subscribe register the listeners for the subscriber.
     * @param  Illuminate\\Events\\Dispatcher  $events
     * @return array
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">subscribe</span><span class="token punctuation">(</span><span class="token variable">$events</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$events</span><span class="token operator">-&gt;</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token keyword static-context">static</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;userLogin&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$events</span><span class="token operator">-&gt;</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.logout&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token keyword static-context">static</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;userLogout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * userLogin handles user login events.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">userLogin</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * userLogout handles user logout events.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">userLogout</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>После определения подписчик может быть зарегистрирован методом <code>Event::subscribe</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">subscribe</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserEventHandler</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете использовать <a href="./application.html">контейнер IoC приложения</a> для разрешения вашего подписчика. Для этого просто передайте имя вашего подписчика в метод <code>subscribe</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">subscribe</span><span class="token punctuation">(</span><span class="token class-name static-context">UserEventHandler</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="треит-event-emitter"><a href="#треит-event-emitter" class="header-anchor">#</a> Трейт Event Emitter</h2><p>Иногда вы хотите привязать события к одному экземпляру объекта. Вы можете использовать альтернативную систему событий, реализовав трейт <code>October\\Rain\\Support\\Traits\\Emitter</code> в вашем классе.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UserManager</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Support<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Emitter</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Этот трейт предоставляет метод для прослушивания событий с помощью <code>bindEvent</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$manager</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">UserManager</span><span class="token punctuation">;</span>
<span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.beforeRegister&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Check if the $user is a spammer</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>fireEvent</code> используется для вызова событий.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$manager</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">UserManager</span><span class="token punctuation">;</span>
<span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.beforeRegister&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Эти события будут происходить только на локальном объекте, в отличие от глобальных событий.</p>`,73))])}const x=l(r,[["render",k]]);export{b as __pageData,x as default};
